class Hund extends Sprite
{
   String name = "???";
   int geschwindigkeit = 1;

   Hund() {
      super(50, 50, SpriteLibrary.Hund, 1);
   }

   public void act() 
   {
      laufen();
      if(isOutsideView())
      {
         System.out.println(name + " gewinnt!"); // Namen ergänzen!
         System.exit(1);
      }
   } 

   void laufen()
   {
      setAngle(0);
      move(geschwindigkeit, 0); 
   }

}

class Pudel extends Hund
{
   String herrchen = "Ute";

   Pudel()
   {
      setImageIndex(4); 
      name = "Mrs. Hudson";
      geschwindigkeit = 25;
      this.moveTo(0, 250);
   }
}

public class Husky extends Hund
